const topics = [
  'How New Paltz locals can read a cannabis COA before they buy',
  'Terpene basics: choosing strains for Hudson Valley hikes',
  'Edibles dosing 101 for first-time New York customers',
  'What New York State legal dispensary licensing means for shoppers',
  'Storing cannabis through Hudson Valley humidity and cold snaps'
];
const week = Math.floor(Date.now() / (7 * 24 * 60 * 60 * 1000));
return [{ json: { topic: topics[week % topics.length] } }];

const raw = $json.choices?.[0]?.message?.content ?? '{}';
const article = JSON.parse(raw);
if (!article.title || !article.bodyHtml) {
  throw new Error('OpenAI response missing title or bodyHtml');
}
return [{ json: { title: article.title, metaDescription: article.metaDescription ?? '', bodyHtml: article.bodyHtml } }];
